import React from 'react';
import './Sidebar.css';
import { Link } from 'react-router-dom'; // Link bileşenini içe aktar

function Sidebar() {
    return (
        <aside className="sidebar">
            <h2>BeeonHive</h2>
            <nav>
                <ul>
                    {/* Admin Paneli için yönlendirme linki */}
                    <li>
                        <Link to="/admin">Admin Paneli</Link>
                    </li>
                    
                    <li>Ürünlere Göz At</li>
                    <li>
                        <Link to="/admin-iletisim">Mesajlar</Link>
                    </li>
                    <li>Çıkış Yap</li>
                </ul>
            </nav>
        </aside>
    );
}

export default Sidebar;
